#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Record {
    char *name;
    int *scores;
};

static void destroy_record(struct Record *record) {
    if (record == NULL) return;
    free(record->scores);
    free(record->name);
    free(record);
}

int main(void) {
    struct Record *record = malloc(sizeof *record);
    if (record == NULL) {
        fputs("record allocation failed\n", stderr);
        return 1;
    }
    record->name = NULL;
    record->scores = NULL;

    record->name = malloc(sizeof "Asha");
    if (record->name == NULL) {
        destroy_record(record);
        return 1;
    }
    memcpy(record->name, "Asha", sizeof "Asha");

    record->scores = malloc(2 * sizeof *record->scores);
    if (record->scores == NULL) {
        destroy_record(record);
        return 1;
    }
    record->scores[0] = 82;
    record->scores[1] = 91;

    printf("%s: %d, %d\n", record->name,
           record->scores[0], record->scores[1]);
    destroy_record(record);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *owner = malloc(sizeof *owner);
    if (owner == NULL) {
        fputs("allocation failed\n", stderr);
        return 1;
    }

    *owner = 42;
    printf("before release: %d\n", *owner);

    free(owner);
    owner = NULL;

    if (owner == NULL) {
        puts("owner no longer refers to an allocation");
    }
    return 0;
}
